import React, { useState, useRef } from 'react';
import cx from 'classnames';
import { Spin } from '@memori.ai/ui';
import { FileText as DocumentIcon } from 'lucide-react';
import { Modal } from '@memori.ai/ui';
import { useTranslation } from 'react-i18next';
import memoriApiClient from '@memori.ai/memori-api-client';
import {
  documentConversionExtensions,
  localTextExtensions,
  officeNativeExtensions,
} from '../../../helpers/constants';
import {
  isLocalTextFilename,
  isOfficeNativeFilename,
} from '../../../helpers/utils';
import { getOriginalMimeType } from '../../MediaWidget/MediaItemWidget.utils';
import {
  convertDocument,
  ConvertDocumentResult,
} from '../../../helpers/convertDocument';
// Types
type PreviewFile = {
  name: string;
  id: string;
  content: string;
  type: 'document';
  previewUrl?: string;
  uploaded?: boolean;
  error?: boolean;
};

export type ProcessedDocumentFile = {
  name: string;
  id: string;
  content: string;
  mimeType: string;
  /** Link written in <attachment_link>: original file when available, else the text asset. */
  attachmentUrl?: string;
  /** True when `content` is only part of the converted text. */
  truncated?: boolean;
  /** Extract length from gateway `meta.caratteri` (after footer strip). */
  shownChars?: number;
  totalChars?: number;
};

// Props interface
interface UploadDocumentsProps {
  setDocumentPreviewFiles: (files: ProcessedDocumentFile[]) => void;
  authToken?: string;
  client?: ReturnType<typeof memoriApiClient>;
  sessionID?: string;
  baseUrl?: string;
  memoriID?: string;
  maxDocuments?: number;
  /** Sent to the conversion API as `max_caratteri`. */
  maxDocumentContentLength?: number;
  documentPreviewFiles: any;
  onLoadingChange?: (loading: boolean, fileCount?: number) => void;
  onDocumentError?: (error: {
    message: string;
    severity: 'error' | 'warning' | 'info';
  }) => void;
  onValidateFile?: (file: File) => boolean;
  onValidatePayloadSize?: (
    newDocuments: {
      name: string;
      id: string;
      content: string;
      mimeType: string;
    }[]
  ) => boolean | { valid: boolean; message?: string };
}

const UploadDocuments: React.FC<UploadDocumentsProps> = ({
  setDocumentPreviewFiles,
  authToken = '',
  client,
  sessionID = '',
  baseUrl = '',
  memoriID = '',
  maxDocuments,
  maxDocumentContentLength,
  documentPreviewFiles,
  onLoadingChange,
  onDocumentError,
  onValidateFile,
  onValidatePayloadSize,
}) => {
  const { t } = useTranslation();
  const { backend } = client || {
    backend: { uploadAsset: null, uploadAssetUnlogged: null },
  };

  // State
  const [isLoading, setIsLoading] = useState(false);
  const [selectedFile, setSelectedFile] = useState<PreviewFile | null>(null);

  // Refs
  const documentInputRef = useRef<HTMLInputElement>(null);

  const setLoadingState = (loading: boolean, fileCount?: number) => {
    setIsLoading(loading);
    onLoadingChange?.(loading, fileCount);
  };

  // Document upload
  const validateDocumentFile = (file: File): boolean => {
    if (onValidateFile) {
      return onValidateFile(file);
    }
    return true;
  };

  // Validate total payload size (returns result object for conditional error display)
  const validatePayloadSize = (
    newDocuments: {
      name: string;
      id: string;
      content: string;
      mimeType: string;
    }[]
  ): { valid: boolean; message?: string } => {
    if (onValidatePayloadSize) {
      const result = onValidatePayloadSize(newDocuments);
      if (typeof result === 'boolean') {
        return result ? { valid: true } : { valid: false, message: '' };
      }
      return result;
    }
    return { valid: true };
  };

  const processDocumentFile = async (
    file: File
  ): Promise<
    Omit<Partial<ConvertDocumentResult>, 'text'> & {
      text: string | null;
      uploadAsOriginal?: boolean;
    }
  > => {
    if (isOfficeNativeFilename(file.name)) {
      return { text: null, uploadAsOriginal: true };
    }

    try {
      if (isLocalTextFilename(file.name)) {
        return { text: await fileToText(file) };
      }
      return await convertDocument(file, {
        sessionID,
        memoriID,
        baseUrl,
        maxChars: maxDocumentContentLength,
      });
    } catch (error) {
      console.error('Document processing failed:', error);
      throw new Error(
        `Failed to process "${file.name}": ${
          error instanceof Error ? error.message : 'Unknown error'
        }`
      );
    }
  };

  const fileToText = (file: File): Promise<string> =>
    new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = e => resolve((e.target?.result as string) || '');
      reader.onerror = () => reject(new Error('File reading failed'));
      reader.readAsText(file, 'UTF-8');
    });

  const fileToDataUrl = (file: File): Promise<string> =>
    new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = e => resolve((e.target?.result as string) || '');
      reader.onerror = () => reject(new Error('File reading failed'));
      reader.readAsDataURL(file);
    });

  const uploadAssetFile = async (file: File): Promise<string> => {
    if (!client) {
      throw new Error('API client not configured properly for media upload');
    }

    const fileDataUrl = await fileToDataUrl(file);
    let response: any;
    if (authToken && backend?.uploadAsset) {
      response = await backend.uploadAsset(file.name, fileDataUrl, authToken);
    } else if (memoriID && sessionID && backend?.uploadAssetUnlogged) {
      response = await backend.uploadAssetUnlogged(
        file.name,
        fileDataUrl,
        memoriID,
        sessionID
      );
    } else {
      throw new Error('Missing required parameters for upload');
    }

    if (!response) {
      throw new Error('Upload failed');
    }
    if (response.resultCode !== 0) {
      throw new Error(response.resultMessage || 'Upload failed');
    }

    const assetURL = response.asset?.assetURL;
    if (!assetURL) {
      throw new Error('Upload failed: missing asset URL');
    }

    return assetURL;
  };

  const handleDocumentUpload = async (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    const files = Array.from(e.target.files || []);
    if (files.length === 0) return;

    // Check current total media count (images + documents)
    const currentMediaCount = documentPreviewFiles.length;
    const remainingSlots = maxDocuments
      ? Math.max(0, maxDocuments - currentMediaCount)
      : files.length;
    const filesToProcess = files.slice(0, remainingSlots);

    if (files.length > filesToProcess.length) {
      const skipped = files.length - filesToProcess.length;
      onDocumentError?.({
        message:
          t('upload.documentsNotAddedMaxAllowed', {
            count: skipped,
            max: maxDocuments ?? 10,
            defaultValue: `${skipped} document(s) not added (maximum ${
              maxDocuments ?? 10
            } files allowed).`,
          }) ??
          `${skipped} document(s) not added (maximum ${
            maxDocuments ?? 10
          } files allowed).`,
        severity: 'warning',
      });
    }

    if (filesToProcess.length === 0) {
      if (documentInputRef.current) {
        documentInputRef.current.value = '';
      }
      return;
    }

    setLoadingState(true, filesToProcess.length);

    try {
      // Process each file
      const processedFiles: ProcessedDocumentFile[] = [];

      let activeCount = filesToProcess.length;

      for (const file of filesToProcess) {
        if (!validateDocumentFile(file)) {
          activeCount--;
          onLoadingChange?.(true, activeCount);
          continue;
        }

        const fileId = Math.random().toString(36).substr(2, 9);

        try {
          const {
            text,
            uploadAsOriginal,
            originalUrl,
            truncated,
            shownChars,
            totalChars,
          } = await processDocumentFile(file);

          if (uploadAsOriginal) {
            // Office native format: upload the original file as asset, no text extraction
            let assetUrl: string | undefined;
            try {
              assetUrl = await uploadAssetFile(file);
            } catch (uploadError) {
              console.error('Office asset upload failed:', uploadError);
              onDocumentError?.({
                message: t('upload.officeAssetUploadFailed', {
                  fileName: file.name,
                  defaultValue: `"${file.name}" could not be uploaded and was not added.`,
                }),
                severity: 'error',
              });
            }

            if (!assetUrl) {
              activeCount--;
              onLoadingChange?.(true, activeCount);
              continue;
            }

            processedFiles.push({
              name: file.name,
              id: fileId,
              content: '',
              mimeType: getOriginalMimeType(file.name, file.type),
              attachmentUrl: assetUrl,
            });
          } else if (text && originalUrl) {
            // Prefer the gateway's signed original-file link (real file download)
            // over uploading a separate text asset. The link typically expires
            // after ~30 days — see ConvertDocumentResult.originalUrl.
            processedFiles.push({
              name: file.name,
              id: fileId,
              content: text,
              mimeType: getOriginalMimeType(file.name, file.type),
              attachmentUrl: originalUrl,
              truncated,
              shownChars,
              totalChars,
            });
          } else if (text) {
            const baseName = file.name.replace(/\.[^/.]+$/, '') || file.name;
            const textFile = new File([text], `${baseName}.txt`, {
              type: 'text/plain',
            });

            let textAssetUrl: string | undefined;
            try {
              textAssetUrl = await uploadAssetFile(textFile);
            } catch (uploadError) {
              console.error('Text asset upload failed:', uploadError);
              onDocumentError?.({
                message: t('upload.partialAssetUploadWarning', {
                  fileName: file.name,
                  defaultValue:
                    'Some file links could not be uploaded, but the document was added anyway.',
                }),
                severity: 'warning',
              });
            }

            processedFiles.push({
              name: file.name,
              id: fileId,
              content: text,
              mimeType: getOriginalMimeType(file.name, file.type),
              attachmentUrl: textAssetUrl,
              truncated,
              shownChars,
              totalChars,
            });
          } else {
            activeCount--;
            onLoadingChange?.(true, activeCount);
          }
        } catch (error) {
          activeCount--;
          onLoadingChange?.(true, activeCount);
          console.error('File processing error:', error);
          onDocumentError?.({
            message: `${
              error instanceof Error ? error.message : 'Unknown error'
            }`,
            severity: 'warning',
          });
        }
      }

      if (processedFiles.length > 0) {
        setDocumentPreviewFiles(
          processedFiles.map(file => ({
            ...file,
            type: 'document',
          }))
        );
      }
    } finally {
      setLoadingState(false);
      if (documentInputRef.current) {
        documentInputRef.current.value = '';
      }
    }
  };

  return (
    <div className="memori--document-upload-wrapper">
      {/* Hidden file input */}
      <input
        ref={documentInputRef}
        type="file"
        accept={[
          ...documentConversionExtensions,
          ...localTextExtensions,
          ...officeNativeExtensions,
        ].join(',')}
        multiple
        className="memori--upload-file-input"
        onChange={handleDocumentUpload}
      />

      {/* Upload document button */}
      <button
        type="button"
        className={cx(
          'memori-button',
          'memori-button--circle',
          'memori-button--icon-only',
          'memori-share-button--button',
          'memori--conversation-button',
          'memori--document-upload-button',
          { 'memori--error': false } // Removed errors.length > 0
        )}
        aria-label={String(
          t('upload.addDocument', { defaultValue: 'Upload document' })
        )}
        onClick={() => documentInputRef.current?.click()}
        disabled={
          isLoading ||
          (maxDocuments && documentPreviewFiles.length >= maxDocuments) ||
          false
        }
      >
        {isLoading ? (
          <Spin spinning className="memori--upload-icon" />
        ) : (
          <React.Fragment>
            <DocumentIcon className="memori--upload-icon" aria-hidden />
          </React.Fragment>
        )}
      </button>

      {/* Modal */}
      <Modal
        width="80%"
        widthMd="80%"
        open={!!selectedFile}
        className="memori--modal-preview-file"
        onClose={() => setSelectedFile(null)}
        closable
        title={selectedFile?.name}
      >
        <div
          className="memori--preview-content"
          style={{
            maxHeight: '70vh',
            overflowY: 'auto',
            textAlign: 'center',
            whiteSpace: 'pre-wrap',
          }}
        >
          {selectedFile?.content}
        </div>
      </Modal>
    </div>
  );
};

export default UploadDocuments;
